1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * When a create request sets {@code sharesHousehold} true and an existing owner already shares this
10	 * owner's last name and address, both are given the same {@code householdId} so the shared household
11	 * is discoverable. The id is a stable identifier derived from the normalized last name and address
12	 * (upper-case hex prefix of their SHA-256), so every member of a household computes the same value.
13	 *
14	 * <p>Last name is compared case-insensitively with collapsed whitespace and address in its normalized
15	 * form (see {@link AddressNormalizer}), matching {@link EnsureUniqueIdentity}, and the id is derived
16	 * from those same normalized values (via {@link OwnerIdentityKey}). Runs after {@link BuildOwner} within the create transaction: it sets
17	 * the id on the new owner (persisted by {@link SaveOwner}) and saves any existing members that did not
18	 * yet carry it. A request without {@code sharesHousehold}, or one with no matching owner, is left
19	 * untouched.
20	 */
21	public class AssignHousehold {
22	
23	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
24	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
25	            return;
26	        }
27	        String lastName = OwnerIdentityKey.normalizeName(owner.getLastName());
28	        String address = AddressNormalizer.normalize(owner.getAddress());
29	        java.util.List<Owner> household = new java.util.ArrayList<>();
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (OwnerIdentityKey.normalizeName(existing.getLastName()).equals(lastName)
32	                    && AddressNormalizer.normalize(existing.getAddress()).equals(address)) {
33	                household.add(existing);
34	            }
35	        }
36	        if (household.isEmpty()) {
37	            return;
38	        }
39	        String householdId = OwnerIdentityKey.householdId(lastName, address);
40	        owner.setHouseholdId(householdId);
41	        for (Owner member : household) {
42	            if (!householdId.equals(member.getHouseholdId())) {
43	                member.setHouseholdId(householdId);
44	                ownerRepository.save(member);
45	            }
46	        }
47	    }
48	}
